function removeRuleLabel(ticketKey, label, rule, repoInfo) {
    if (!ticketKey || !label) return;
    try {
        if (rule && rule.source === 'github') {
            var n = /(\d+)$/.exec(String(ticketKey));
            // gh-683 bug D (live fa #1194, 2026-10-04): the call carried NO
